class EditorState { constructor(private text: string) {} getText() { return this.text } }
class Editor {
  private text = ''
  setText(t: string) { this.text = t }
  save() { return new Snapshot(this.text) }
  restore(s: Snapshot) { this.text = s.get() }
}
class Snapshot { constructor(private state: string) {} get() { return this.state } }

class State { items: string[]; constructor(items: string[]) { this.items = items } }
class Editor {
  private state = new State([])
  save() { return new Snapshot(this.state) }
  restore(s: Snapshot) { this.state = s.get() }
  add(item: string) { this.state.items.push(item) }
}
class Snapshot { constructor(private stateRef: State) { } get() { return this.stateRef } }

// Version A: immutable snapshots via copy
class DocState { constructor(public text: string) {} }
class EditorA {
  private state = new DocState('')
  setText(t: string) { this.state.text = t }
  save() { return new DocState(this.state.text) }
  restore(s: DocState) { this.state = s }
}

// Version B: snapshot returns internal reference
class EditorB {
  private state = { text: '' }
  setText(t: string) { this.state.text = t }
  save() { return this.state }
  restore(s: any) { this.state = s }
}
